/* Portable C model tests for the 50-floor campaign save format.
 *
 * Built against tests/tower_floors_stub.c while main/tower_floors.c is being
 * generated by the parallel workstream; the stub exposes the real
 * tower_floor_desc_t interface, so these tests exercise main/tower.c only. */
#include "tower.h"

#include <assert.h>
#include <stdio.h>
#include <string.h>

#define BITMAP_OFFSET (12u + TOWER_SAVE_FIELDS * 4u)
#define RESERVED_OFFSET (12u + (TOWER_SAVE_FIELDS - 1u) * 4u)
#define FIELD_OFFSET(i) (12u + (unsigned)(i) * 4u)
#define MAX_CELLS (19u * 19u)

static tower_snapshot_t state_of(tower_handle_t t)
{
    tower_snapshot_t s;
    assert(tower_read(t, &s) == TOWER_OK);
    return s;
}

static void export_of(tower_handle_t t, uint8_t *bytes)
{
    assert(tower_export(t, bytes, TOWER_SAVE_BYTES) == TOWER_OK);
}

static void import_into(tower_handle_t t, const uint8_t *bytes)
{
    assert(tower_import(t, bytes, TOWER_SAVE_BYTES) == TOWER_OK);
}

static uint32_t save_checksum(const uint8_t *b)
{
    uint32_t hash = 2166136261u;
    unsigned i;
    for (i = 0; i < TOWER_SAVE_BYTES; ++i) {
        if (i < 8u || i > 11u) hash = (hash ^ b[i]) * 16777619u;
    }
    return hash;
}

static void fix_checksum(uint8_t *b)
{
    uint32_t hash = save_checksum(b);
    unsigned i;
    for (i = 0; i < 4u; ++i) b[8u + i] = (uint8_t)(hash >> (8u * i));
}

/* Counts set bits in the per-floor consumed bitmap region. */
static unsigned bits_set(const uint8_t *b)
{
    unsigned i, bits = 0, bit;
    for (i = BITMAP_OFFSET; i < TOWER_SAVE_BYTES; ++i) {
        for (bit = 0; bit < 8u; ++bit) bits += (b[i] >> bit) & 1u;
    }
    return bits;
}

/* The stub floors share the same top row, so climbing one floor is a fixed
 * 4-step pattern: secret wall, walk through it, event tile, up stair. */
static void step_up_floor(tower_handle_t t)
{
    unsigned f = state_of(t).floor;
    assert(tower_move(t, 1, 0) == TOWER_STATUS_SECRET);
    assert(tower_move(t, 1, 0) == TOWER_STATUS_MOVED);
    assert(tower_move(t, 1, 0) == TOWER_STATUS_EVENT);
    assert(tower_move(t, 1, 0) == TOWER_STATUS_STAIRS);
    assert(state_of(t).floor == f + 1u);
    assert(state_of(t).x == 1 && state_of(t).y == 1);
}

static void climb_to_top(tower_handle_t t)
{
    while (state_of(t).floor < TOWER_FLOORS - 1u) step_up_floor(t);
}

/* Walk from the gate floor's spawn (1,1) to its goal tile at (gx,1). */
static void take_goal(tower_handle_t t, unsigned gx, tower_status_t expected)
{
    tower_snapshot_t s;
    assert(tower_move(t, 1, 0) == TOWER_STATUS_SECRET);
    assert(tower_move(t, 1, 0) == TOWER_STATUS_MOVED);
    assert(tower_move(t, 1, 0) == TOWER_STATUS_EVENT);
    assert(tower_move(t, 0, 1) == TOWER_STATUS_MOVED);
    for (;;) {
        s = state_of(t);
        if (s.x == gx) break;
        assert(tower_move(t, 1, 0) == TOWER_STATUS_MOVED);
    }
    assert(tower_move(t, 0, -1) == expected);
}

static uint32_t get32(const uint8_t *b, unsigned offset)
{
    return (uint32_t)b[offset] | (uint32_t)b[offset + 1u] << 8 |
           (uint32_t)b[offset + 2u] << 16 | (uint32_t)b[offset + 3u] << 24;
}

/* Hand-computed offsets: independently pins the required field order, the
 * reserved 29th slot and the bitmap origin. */
static void test_wire_layout(void)
{
    tower_handle_t a = NULL;
    uint8_t b[TOWER_SAVE_BYTES];

    assert(tower_create(NULL, &a) == TOWER_OK);
    export_of(a, b);
    assert(memcmp(b, "MTWR", 4) == 0);
    assert(b[4] == 7u && b[5] == 0u && b[6] == 0x48u && b[7] == 0x0au);
    assert(get32(b, 8) == save_checksum(b));
    assert(get32(b, FIELD_OFFSET(0)) == (uint32_t)TOWER_PHASE_PLAY);
    assert(get32(b, FIELD_OFFSET(1)) == (uint32_t)TOWER_STATUS_READY);
    assert(get32(b, FIELD_OFFSET(2)) == 0u);  /* floor */
    assert(get32(b, FIELD_OFFSET(3)) == 1u);  /* x */
    assert(get32(b, FIELD_OFFSET(4)) == 1u);  /* y */
    assert(get32(b, FIELD_OFFSET(5)) == 100u);
    assert(get32(b, FIELD_OFFSET(6)) == 12u);
    assert(get32(b, FIELD_OFFSET(7)) == 4u);
    assert(get32(b, FIELD_OFFSET(8)) == 0u);
    assert(get32(b, FIELD_OFFSET(9)) == 0u);
    assert(get32(b, FIELD_OFFSET(10)) == 0u);
    assert(get32(b, FIELD_OFFSET(11)) == 0u); /* gold */
    assert(get32(b, FIELD_OFFSET(12)) == 0u); /* turns */
    assert(get32(b, FIELD_OFFSET(13)) == 0u); /* shop_attack */
    assert(get32(b, FIELD_OFFSET(14)) == 0u); /* shop_defence */
    assert(get32(b, FIELD_OFFSET(15)) == 0u); /* cleared */
    assert(get32(b, FIELD_OFFSET(16)) == 1u); /* explored_lo */
    assert(get32(b, FIELD_OFFSET(17)) == 0u); /* explored_hi */
    assert(get32(b, FIELD_OFFSET(18)) == 0u); /* pending_x */
    assert(get32(b, FIELD_OFFSET(19)) == 0u); /* pending_y */
    assert(get32(b, FIELD_OFFSET(20)) == 0u); /* pending.tile */
    assert(get32(b, FIELD_OFFSET(21)) == 0u);
    assert(get32(b, FIELD_OFFSET(22)) == 0u);
    assert(get32(b, FIELD_OFFSET(23)) == 0u);
    assert(get32(b, FIELD_OFFSET(24)) == 0u);
    assert(get32(b, FIELD_OFFSET(25)) == 0u);
    assert(get32(b, FIELD_OFFSET(26)) == 0u);
    assert(get32(b, FIELD_OFFSET(27)) == 0u); /* pending.winnable */
    assert(get32(b, FIELD_OFFSET(28)) == 0u); /* chapters */
    assert(get32(b, RESERVED_OFFSET) == 0u);
    assert(BITMAP_OFFSET == 132u);

    /* A pending combat record lands in fields 18..27, in snapshot order. */
    assert(tower_move(a, 0, 1) == TOWER_STATUS_CONFIRM);
    export_of(a, b);
    assert(get32(b, FIELD_OFFSET(0)) == (uint32_t)TOWER_PHASE_COMBAT);
    assert(get32(b, FIELD_OFFSET(1)) == (uint32_t)TOWER_STATUS_CONFIRM);
    assert(get32(b, FIELD_OFFSET(18)) == 1u); /* pending_x */
    assert(get32(b, FIELD_OFFSET(19)) == 2u); /* pending_y */
    assert(get32(b, FIELD_OFFSET(20)) == (uint32_t)TOWER_TILE_SLIME);
    assert(get32(b, FIELD_OFFSET(21)) == 24u); /* pending.hp */
    assert(get32(b, FIELD_OFFSET(22)) == 6u);
    assert(get32(b, FIELD_OFFSET(23)) == 2u);
    assert(get32(b, FIELD_OFFSET(24)) == 3u);  /* pending.gold */
    assert(get32(b, FIELD_OFFSET(25)) == 4u);  /* pending.damage */
    assert(get32(b, FIELD_OFFSET(26)) == 3u);  /* pending.rounds */
    assert(get32(b, FIELD_OFFSET(27)) == 1u);  /* pending.winnable */

    tower_delete(a);
    puts("ok: wire offsets match tower_snapshot_t order plus one reserved slot");
}

static void test_header_shape(void)
{
    tower_handle_t t = NULL;
    uint8_t bytes[TOWER_SAVE_BYTES];
    printf("TOWER_SAVE_BYTES = %u (header %u + fields %u + bitmap %u)\n",
           (unsigned)TOWER_SAVE_BYTES, 12u,
           (unsigned)TOWER_SAVE_FIELDS * 4u,
           (unsigned)TOWER_FLOORS * TOWER_FLAG_BYTES);
    assert(TOWER_SAVE_BYTES == 2632u);
    assert(TOWER_FLOORS == 50u);
    assert(tower_floors() == TOWER_FLOORS);
    assert(tower_floor_width() == TOWER_FLOOR_W);
    assert(tower_floor_height() == TOWER_FLOOR_H);
    assert(tower_create(NULL, &t) == TOWER_OK);
    export_of(t, bytes);
    assert(memcmp(bytes, "MTWR", 4) == 0);
    assert(bytes[4] == 7u);
    assert(bytes[5] == 0u);
    assert(((unsigned)bytes[6] | ((unsigned)bytes[7] << 8)) ==
           TOWER_SAVE_BYTES);
    assert(TOWER_FLOORS * TOWER_FLAG_BYTES == 2500u);
    tower_delete(t);
    puts("ok: version-7 header and 2500-byte constant bitmap geometry");
}

static void test_new_game_round_trip(void)
{
    tower_handle_t a = NULL, b = NULL;
    tower_snapshot_t s;
    uint8_t first[TOWER_SAVE_BYTES], second[TOWER_SAVE_BYTES];

    assert(tower_create(NULL, &a) == TOWER_OK);
    assert(tower_create(NULL, &b) == TOWER_OK);

    s = state_of(a);
    assert(s.floor == 0 && s.x == 1 && s.y == 1);
    assert(s.hp == 100 && s.attack == 12 && s.defence == 4);
    assert(s.gold == 0 && s.turns == 0 && !s.cleared);
    assert(s.chapters == 0u);
    assert(s.phase == TOWER_PHASE_PLAY && s.status == TOWER_STATUS_READY);
    assert(tower_anchor_unlocked(&s, 0));
    assert(!tower_anchor_unlocked(&s, 1));
    assert(!tower_anchor_unlocked(&s, TOWER_ANCHORS));
    assert(tower_anchor_floor(0) == 0u && tower_anchor_floor(1) == 9u);
    assert(tower_anchor_floor(2) == 19u && tower_anchor_floor(3) == 29u);
    assert(tower_anchor_floor(4) == 39u);
    assert(tower_anchor_floor(TOWER_ANCHORS - 1u) == TOWER_FLOORS - 1u);
    assert(s.pending.tile == TOWER_TILE_FLOOR && !s.pending.winnable);
    assert(tower_explored(&s, 0));
    assert(!tower_explored(&s, 1));
    assert(tower_tile_current(a, 1, 1) == TOWER_TILE_DOWN);
    assert(tower_tile_current(a, 2, 1) == TOWER_TILE_SECRET);
    assert(tower_tile_current(a, 3, 1) == TOWER_TILE_EVENT);
    assert(tower_tile_current(a, 4, 1) == TOWER_TILE_UP);
    assert(tower_tile_current(a, 1, 2) == TOWER_TILE_SLIME);
    assert(tower_tile_current(a, 1, 3) == TOWER_TILE_KNIGHT);
    assert(tower_tile_current(a, 1, 4) == TOWER_TILE_GOLEM);
    assert(tower_tile_current(a, 0, 0) == TOWER_TILE_WALL);
    assert(tower_tile_current(a, -1, 1) == TOWER_TILE_WALL);
    assert(tower_tile_current(a, 11, 1) == TOWER_TILE_WALL);

    export_of(a, first);
    assert(bits_set(first) == 0);
    import_into(b, first);
    assert(tower_hash(a) == tower_hash(b));
    export_of(b, second);
    assert(memcmp(first, second, TOWER_SAVE_BYTES) == 0);

    tower_delete(a);
    tower_delete(b);
    puts("ok: new game -> save -> import -> save is byte-identical");
}

static void test_kill_enemy_marks_one_bit(void)
{
    tower_handle_t a = NULL, b = NULL;
    tower_snapshot_t s;
    uint8_t saved[TOWER_SAVE_BYTES];
    uint32_t hash;

    assert(tower_create(NULL, &a) == TOWER_OK);
    assert(tower_create(NULL, &b) == TOWER_OK);

    assert(tower_move(a, 0, 1) == TOWER_STATUS_CONFIRM);
    s = state_of(a);
    assert(s.phase == TOWER_PHASE_COMBAT);
    assert(s.status == TOWER_STATUS_CONFIRM);
    assert(s.pending.tile == TOWER_TILE_SLIME);
    assert(s.pending.hp == 24 && s.pending.attack == 6 &&
           s.pending.defence == 2 && s.pending.gold == 3);
    assert(s.pending.rounds == 3 && s.pending.damage == 4);
    assert(s.pending.winnable);
    assert(s.pending_x == 1 && s.pending_y == 2);

    assert(tower_confirm(a) == TOWER_STATUS_VICTORY);
    s = state_of(a);
    assert(s.phase == TOWER_PHASE_PLAY);
    assert(s.status == TOWER_STATUS_VICTORY);
    assert(s.hp == 96 && s.gold == 3 && s.turns == 1);
    assert(s.x == 1 && s.y == 2);
    assert(tower_tile_current(a, 1, 2) == TOWER_TILE_FLOOR);
    assert(tower_tile_current(a, 2, 1) == TOWER_TILE_SECRET);

    export_of(a, saved);
    assert(bits_set(saved) == 1);
    /* Bitmap index is y*19+x = 2*19+1 = 39 -> byte 4, bit 7. */
    assert(saved[BITMAP_OFFSET + 4] == 0x80);
    assert(saved[BITMAP_OFFSET] == 0x00);

    hash = tower_hash(a);
    import_into(b, saved);
    assert(tower_hash(b) == hash);
    assert(tower_tile(b, 0, 1, 2) == TOWER_TILE_FLOOR);
    assert(tower_tile(b, 0, 2, 1) == TOWER_TILE_SECRET);
    assert(state_of(b).gold == 3 && state_of(b).hp == 96);

    tower_delete(a);
    tower_delete(b);
    puts("ok: killing an enemy sets exactly one bitmap bit and imports back");
}

static void test_losing_fight_is_lethal_but_keeps_enemy(void)
{
    tower_handle_t a = NULL, b = NULL;
    tower_snapshot_t s;
    uint8_t saved[TOWER_SAVE_BYTES];

    assert(tower_create(NULL, &a) == TOWER_OK);
    assert(tower_create(NULL, &b) == TOWER_OK);

    assert(tower_move(a, 1, 0) == TOWER_STATUS_SECRET);
    assert(tower_move(a, 1, 0) == TOWER_STATUS_MOVED);
    assert(tower_move(a, 0, 1) == TOWER_STATUS_MOVED);
    assert(tower_move(a, 0, 1) == TOWER_STATUS_MOVED);
    assert(state_of(a).x == 2 && state_of(a).y == 3);

    /* Knight: player attack 12 > defence 8, so combat is offered even though
     * the preview damage (272) is lethal. */
    assert(tower_move(a, -1, 0) == TOWER_STATUS_CONFIRM);
    s = state_of(a);
    assert(s.phase == TOWER_PHASE_COMBAT);
    assert(s.pending.tile == TOWER_TILE_KNIGHT);
    assert(s.pending.damage == 272u);
    assert(!s.pending.winnable);
    assert(s.pending.damage >= s.hp);

    assert(tower_confirm(a) == TOWER_STATUS_DEAD);
    s = state_of(a);
    assert(s.hp == 0);
    assert(s.status == TOWER_STATUS_DEAD);
    assert(s.phase == TOWER_PHASE_PLAY);
    assert(s.x == 2 && s.y == 3);
    assert(s.gold == 0);
    assert(s.pending_x == 0 && s.pending_y == 0);
    assert(tower_tile_current(a, 1, 3) == TOWER_TILE_KNIGHT);
    assert(tower_tile_current(a, 1, 2) == TOWER_TILE_SLIME);

    export_of(a, saved);
    assert(bits_set(saved) == 1); /* only the secret wall was consumed */
    import_into(b, saved);
    s = state_of(b);
    assert(s.hp == 0 && s.status == TOWER_STATUS_DEAD);
    assert(tower_tile(b, 0, 1, 3) == TOWER_TILE_KNIGHT);

    /* A dead run cannot move, shop or teleport. */
    assert(tower_move(a, 0, 1) == TOWER_STATUS_DEAD);
    assert(tower_buy(a, 0) == TOWER_STATUS_DEAD);
    assert(tower_teleport(a, 0) == TOWER_STATUS_DEAD);

    tower_delete(a);
    tower_delete(b);
    puts("ok: losing fight sets hp 0 / DEAD and leaves the enemy tile in place");
}

static void test_secret_wall_is_permanent(void)
{
    tower_handle_t a = NULL, b = NULL;
    tower_snapshot_t s;
    uint8_t saved[TOWER_SAVE_BYTES];

    assert(tower_create(NULL, &a) == TOWER_OK);
    assert(tower_create(NULL, &b) == TOWER_OK);

    assert(tower_move(a, 1, 0) == TOWER_STATUS_SECRET);
    s = state_of(a);
    assert(s.x == 1 && s.y == 1); /* opening the wall does not move the player */
    assert(s.phase == TOWER_PHASE_PLAY);
    assert(tower_tile_current(a, 2, 1) == TOWER_TILE_FLOOR);
    export_of(a, saved);
    assert(bits_set(saved) == 1);

    import_into(b, saved);
    assert(tower_tile(b, 0, 2, 1) == TOWER_TILE_FLOOR);
    assert(tower_tile(a, 0, 2, 1) == TOWER_TILE_FLOOR);

    assert(tower_move(a, 1, 0) == TOWER_STATUS_MOVED);
    assert(state_of(a).x == 2 && state_of(a).y == 1);
    assert(tower_move(a, 0, 0) == TOWER_STATUS_WALL);
    assert(state_of(a).turns == 2);

    tower_delete(a);
    tower_delete(b);
    puts("ok: secret wall opens on bump and stays floor across save/import");
}

static void test_event_tile(void)
{
    tower_handle_t a = NULL;
    tower_snapshot_t s;
    uint8_t saved[TOWER_SAVE_BYTES];

    assert(tower_create(NULL, &a) == TOWER_OK);
    assert(tower_move(a, 1, 0) == TOWER_STATUS_SECRET);
    assert(tower_move(a, 1, 0) == TOWER_STATUS_MOVED);
    assert(tower_move(a, 1, 0) == TOWER_STATUS_EVENT);
    s = state_of(a);
    assert(s.x == 3 && s.y == 1);
    assert(tower_tile_current(a, 3, 1) == TOWER_TILE_FLOOR);
    export_of(a, saved);
    assert(bits_set(saved) == 2); /* secret and event */
    assert(tower_status_text(TOWER_STATUS_SECRET)[0] != '\0');
    assert(tower_status_text(TOWER_STATUS_EVENT)[0] != '\0');
    assert(tower_status_text(TOWER_STATUS_DEAD)[0] != '\0');
    tower_delete(a);
    puts("ok: event tile is walkable, consumed, and returns TOWER_STATUS_EVENT");
}

static void test_teleport_anchors(void)
{
    tower_handle_t a = NULL, b = NULL;
    tower_snapshot_t s;
    uint8_t saved[TOWER_SAVE_BYTES];
    uint32_t turns;

    assert(tower_create(NULL, &a) == TOWER_OK);
    assert(tower_create(NULL, &b) == TOWER_OK);

    /* Floor 1 is the only open anchor; chapter anchors report LOCKED and cost
     * nothing, out-of-range anchors are an argument error. */
    turns = state_of(a).turns;
    assert(tower_teleport(a, 1) == TOWER_STATUS_LOCKED);
    assert(tower_teleport(a, TOWER_ANCHORS) == TOWER_STATUS_WALL);
    assert(tower_teleport(a, TOWER_ANCHORS + 7u) == TOWER_STATUS_WALL);
    s = state_of(a);
    assert(s.floor == 0 && s.x == 1 && s.y == 1);
    assert(s.turns == turns && s.gold == 0);

    /* Standing on the anchor is a no-op, not a floor change. */
    assert(tower_teleport(a, 0) == TOWER_STATUS_READY);
    s = state_of(a);
    assert(s.floor == 0 && s.x == 1 && s.y == 1);

    /* Climbing does not complete a chapter: anchors unlock on the gate tile. */
    while (state_of(a).floor < 9u) step_up_floor(a);
    assert(state_of(a).chapters == 0u);
    assert(tower_teleport(a, 1) == TOWER_STATUS_LOCKED);

    take_goal(a, 8, TOWER_STATUS_CHAPTER);
    s = state_of(a);
    assert(s.chapters == 0x01u);
    assert(!s.cleared);
    assert(tower_anchor_unlocked(&s, 1));
    assert(!tower_anchor_unlocked(&s, 2));

    /* Anchor 10 lands on the floor's down stair and costs no turn. */
    assert(tower_teleport(a, 0) == TOWER_STATUS_STAIRS);
    assert(state_of(a).floor == 0u);
    turns = state_of(a).turns;
    assert(tower_teleport(a, 1) == TOWER_STATUS_STAIRS);
    s = state_of(a);
    assert(s.floor == 9u && s.x == 1 && s.y == 1);
    assert(s.turns == turns);
    assert(tower_tile_current(a, 1, 1) == TOWER_TILE_DOWN);

    /* Chapter state survives the save round trip. */
    export_of(a, saved);
    import_into(b, saved);
    assert(tower_hash(a) == tower_hash(b));
    assert(state_of(b).chapters == 0x01u);
    {
        const tower_snapshot_t sb = state_of(b);
        assert(tower_anchor_unlocked(&sb, 1));
    }

    tower_delete(a);
    tower_delete(b);
    puts("ok: anchors unlock on chapter gates, teleport is free and saves chapters");
}

static void test_floor_shapes(void)
{
    tower_handle_t a = NULL;

    assert(tower_create(NULL, &a) == TOWER_OK);

    /* 11x11 floor: x/y 10 is the wall border, 11 is outside the shape. */
    assert(tower_tile(a, 0, 10, 1) == TOWER_TILE_WALL);
    assert(tower_tile(a, 0, 11, 1) == TOWER_TILE_WALL);
    assert(tower_tile(a, 0, 1, 11) == TOWER_TILE_WALL);
    assert(tower_tile(a, 25, 12, 12) == TOWER_TILE_WALL);
    assert(tower_tile(a, 49, 18, 18) == TOWER_TILE_WALL);

    while (state_of(a).floor < 25u) step_up_floor(a);
    assert(state_of(a).floor == 25);
    /* 13x13 floor: the interior extends to x/y 11. */
    assert(tower_tile_current(a, 11, 1) == TOWER_TILE_FLOOR);
    assert(tower_tile_current(a, 12, 1) == TOWER_TILE_WALL);
    assert(tower_tile_current(a, 11, 11) == TOWER_TILE_FLOOR);
    assert(tower_tile_current(a, 12, 12) == TOWER_TILE_WALL);

    while (state_of(a).floor < 49u) step_up_floor(a);
    assert(state_of(a).floor == 49);
    /* 19x19 floor: the largest shape the fixed bitmap reserves. */
    assert(tower_tile_current(a, 17, 2) == TOWER_TILE_FLOOR);
    assert(tower_tile_current(a, 18, 1) == TOWER_TILE_WALL);
    assert(tower_tile_current(a, 17, 17) == TOWER_TILE_FLOOR);
    assert(tower_tile_current(a, 18, 18) == TOWER_TILE_WALL);

    tower_delete(a);
    puts("ok: 11x11, 13x13 and 19x19 floors decode through one bitmap layout");
}

static void test_chapter_gate(void)
{
    tower_handle_t a = NULL, b = NULL;
    tower_snapshot_t s;
    uint8_t saved[TOWER_SAVE_BYTES];

    assert(tower_create(NULL, &a) == TOWER_OK);
    assert(tower_create(NULL, &b) == TOWER_OK);

    while (state_of(a).floor < 9u) step_up_floor(a);
    take_goal(a, 8, TOWER_STATUS_CHAPTER);
    s = state_of(a);
    assert(!s.cleared);
    assert(s.status == TOWER_STATUS_CHAPTER);
    assert(s.chapters == 0x01u);
    assert(tower_chapter_complete(&s, 1));
    assert(!tower_chapter_complete(&s, 2));
    assert(tower_tile_current(a, 8, 1) == TOWER_TILE_FLOOR);
    assert(tower_status_text(TOWER_STATUS_CHAPTER)[0] != '\0');
    assert(tower_status_text(TOWER_STATUS_LOCKED)[0] != '\0');

    export_of(a, saved);
    import_into(b, saved);
    assert(!state_of(b).cleared);
    assert(state_of(b).chapters == 0x01u);
    assert(tower_hash(a) == tower_hash(b));

    tower_delete(a);
    tower_delete(b);
    puts("ok: a chapter gate consumes 'G' and lights the chapter, not the tower");
}

static void test_final_goal(void)
{
    tower_handle_t a = NULL, b = NULL;
    tower_snapshot_t s;
    uint8_t saved[TOWER_SAVE_BYTES];

    assert(tower_create(NULL, &a) == TOWER_OK);
    assert(tower_create(NULL, &b) == TOWER_OK);

    climb_to_top(a);
    assert(state_of(a).floor == 49u);
    take_goal(a, 17, TOWER_STATUS_CLEARED);
    s = state_of(a);
    assert(s.cleared);
    /* The climb crossed four chapter exits; the last gate lights chapter five. */
    assert(s.chapters == 0x1Fu);
    assert(tower_chapter_complete(&s, 5));
    assert(tower_anchor_unlocked(&s, 5));

    export_of(a, saved);
    import_into(b, saved);
    assert(state_of(b).cleared);
    assert(state_of(b).chapters == 0x1Fu);
    assert(tower_hash(a) == tower_hash(b));

    tower_delete(a);
    tower_delete(b);
    puts("ok: only the last floor's 'G' ends the campaign and lights chapter 5");
}

static void test_chapter_exit_stair(void)
{
    tower_handle_t a = NULL, b = NULL;
    tower_snapshot_t s;
    uint8_t saved[TOWER_SAVE_BYTES];

    assert(tower_create(NULL, &a) == TOWER_OK);
    assert(tower_create(NULL, &b) == TOWER_OK);
    while (state_of(a).floor < 9u) step_up_floor(a);
    assert(state_of(a).chapters == 0u);
    step_up_floor(a);
    s = state_of(a);
    assert(s.floor == 10u);
    assert(s.chapters == 0x01u);
    assert(tower_anchor_unlocked(&s, 1));
    assert(!s.cleared);

    export_of(a, saved);
    import_into(b, saved);
    assert(state_of(b).chapters == 0x01u);
    assert(tower_hash(a) == tower_hash(b));
    tower_delete(a);
    tower_delete(b);
    puts("ok: leaving a chapter through its exit stair records the chapter");
}

static void test_enemy_scaling(void)
{
    tower_handle_t a = NULL;
    tower_snapshot_t s;
    tower_enemy_preview_t p;
    uint8_t saved[TOWER_SAVE_BYTES];

    assert(tower_create(NULL, &a) == TOWER_OK);

    /* Floor 0 is the unscaled baseline. */
    assert(tower_enemy_preview(a, TOWER_TILE_SLIME, &p) == TOWER_OK);
    assert(p.hp == 24 && p.attack == 6 && p.defence == 2 && p.gold == 3);
    assert(p.damage == 4 && p.rounds == 3 && p.winnable);

    assert(tower_enemy_preview(a, TOWER_TILE_KNIGHT, &p) == TOWER_OK);
    assert(p.damage == 272 && !p.winnable);

    /* Refused only when the player cannot damage the enemy at all. */
    assert(tower_enemy_preview(a, TOWER_TILE_GOLEM, &p) == TOWER_OK);
    assert(p.defence == 16 && p.damage == UINT32_MAX && !p.winnable);
    assert(tower_move(a, 1, 0) == TOWER_STATUS_SECRET);
    assert(tower_move(a, 1, 0) == TOWER_STATUS_MOVED);
    assert(tower_move(a, 0, 1) == TOWER_STATUS_MOVED);
    assert(tower_move(a, 0, 1) == TOWER_STATUS_MOVED);
    assert(tower_move(a, 0, 1) == TOWER_STATUS_MOVED);
    assert(state_of(a).x == 2 && state_of(a).y == 4);
    {
        uint32_t turns = state_of(a).turns;
        assert(tower_move(a, -1, 0) == TOWER_STATUS_TOO_STRONG);
        s = state_of(a);
        assert(s.phase == TOWER_PHASE_PLAY);
        assert(s.status == TOWER_STATUS_TOO_STRONG);
        assert(s.x == 2 && s.y == 4);
        assert(s.turns == turns);
        assert(tower_tile_current(a, 1, 4) == TOWER_TILE_GOLEM);
    }

    tower_new(a);
    climb_to_top(a);
    s = state_of(a);
    assert(s.floor == 49 && s.x == 1 && s.y == 1);
    assert(tower_explored(&s, 49));
    assert(tower_explored(&s, 0) && tower_explored(&s, 17) &&
           tower_explored(&s, 33));

    assert(tower_enemy_preview(a, TOWER_TILE_SLIME, &p) == TOWER_OK);
    assert(p.hp == 24u * 590u / 100u);
    assert(p.hp == 141u);
    assert(p.attack == 6u * 590u / 100u);
    assert(p.defence == 2u * 590u / 100u);
    assert(p.gold == 3u); /* gold is never scaled */
    assert(!p.winnable);

    /* The scaled preview round-trips through the save validator. */
    export_of(a, saved);
    {
        tower_handle_t b = NULL;
        assert(tower_create(NULL, &b) == TOWER_OK);
        import_into(b, saved);
        assert(tower_hash(a) == tower_hash(b));
        tower_delete(b);
    }

    tower_delete(a);
    puts("ok: floor-f scaling is base*(100+10f)/100 on hp/atk/def, gold unscaled");
}

static void test_combat_save_round_trip(void)
{
    tower_handle_t a = NULL, b = NULL;
    tower_snapshot_t s;
    uint8_t saved[TOWER_SAVE_BYTES], changed[TOWER_SAVE_BYTES];

    assert(tower_create(NULL, &a) == TOWER_OK);
    assert(tower_create(NULL, &b) == TOWER_OK);

    assert(tower_move(a, 0, 1) == TOWER_STATUS_CONFIRM);
    export_of(a, saved);
    import_into(b, saved);
    assert(tower_hash(a) == tower_hash(b));
    s = state_of(b);
    assert(s.phase == TOWER_PHASE_COMBAT);
    assert(s.pending.tile == TOWER_TILE_SLIME);
    assert(s.pending.winnable && s.pending.damage == 4);
    assert(tower_confirm(b) == TOWER_STATUS_VICTORY);

    /* Cancel restores play without consuming the enemy. */
    tower_new(a);
    assert(tower_move(a, 0, 1) == TOWER_STATUS_CONFIRM);
    assert(tower_cancel(a) == TOWER_STATUS_CANCELLED);
    s = state_of(a);
    assert(s.phase == TOWER_PHASE_PLAY);
    assert(tower_tile_current(a, 1, 2) == TOWER_TILE_SLIME);
    assert(s.x == 1 && s.y == 1);
    assert(s.turns == 0);

    /* Losing pending combat is a legal save. */
    tower_new(a);
    assert(tower_move(a, 1, 0) == TOWER_STATUS_SECRET);
    assert(tower_move(a, 1, 0) == TOWER_STATUS_MOVED);
    assert(tower_move(a, 0, 1) == TOWER_STATUS_MOVED);
    assert(tower_move(a, 0, 1) == TOWER_STATUS_MOVED);
    assert(tower_move(a, -1, 0) == TOWER_STATUS_CONFIRM);
    export_of(a, saved);
    import_into(b, saved);
    assert(tower_hash(a) == tower_hash(b));
    assert(state_of(b).pending.winnable == false);

    /* A tampered pending damage is rejected even with a valid checksum. */
    memcpy(changed, saved, sizeof saved);
    changed[FIELD_OFFSET(25)] ^= 0x01u; /* pending.damage */
    fix_checksum(changed);
    assert(tower_import(b, changed, sizeof changed) == TOWER_ERR_SAVE);

    tower_delete(a);
    tower_delete(b);
    puts("ok: combat (winning and losing) saves round-trip and validate");
}

static void test_corrupt_imports(void)
{
    tower_handle_t a = NULL, b = NULL;
    tower_snapshot_t s;
    uint8_t saved[TOWER_SAVE_BYTES], changed[TOWER_SAVE_BYTES];
    uint32_t hash;
    unsigned i;

    assert(tower_create(NULL, &a) == TOWER_OK);
    assert(tower_create(NULL, &b) == TOWER_OK);
    climb_to_top(a);
    export_of(a, saved);
    import_into(b, saved);
    assert(tower_hash(a) == tower_hash(b));
    hash = tower_hash(b);
    s = state_of(b);
    assert(s.floor == 49);
    /* The climb consumes two cells on floors 0..48 (secret + event); the
     * arrival floor 49 is untouched, so 49 * 2 = 98 bits are set. */
    assert(bits_set(saved) == 98);

    /* Every single flipped byte must be rejected transactionally. */
    for (i = 0; i < TOWER_SAVE_BYTES; ++i) {
        memcpy(changed, saved, sizeof saved);
        changed[i] ^= 0x80u;
        assert(tower_import(b, changed, sizeof changed) == TOWER_ERR_SAVE);
        assert(tower_hash(b) == hash);
    }

    /* Semantic corruption with a recomputed checksum is still rejected. */
    memcpy(changed, saved, sizeof saved);
    changed[RESERVED_OFFSET] = 1;
    fix_checksum(changed);
    assert(tower_import(b, changed, sizeof changed) == TOWER_ERR_SAVE);

    memcpy(changed, saved, sizeof saved);
    changed[BITMAP_OFFSET + MAX_CELLS / 8u] |= (uint8_t)(1u << (MAX_CELLS % 8u));
    fix_checksum(changed);
    assert(tower_import(b, changed, sizeof changed) == TOWER_ERR_SAVE);

    memcpy(changed, saved, sizeof saved);
    changed[BITMAP_OFFSET] |= 0x01u; /* floor 0, (0,0), a wall */
    fix_checksum(changed);
    assert(tower_import(b, changed, sizeof changed) == TOWER_ERR_SAVE);

    memcpy(changed, saved, sizeof saved);
    changed[BITMAP_OFFSET + 3u] |= 0x01u; /* floor 0, (5,1), plain floor */
    fix_checksum(changed);
    assert(tower_import(b, changed, sizeof changed) == TOWER_ERR_SAVE);

    memcpy(changed, saved, sizeof saved);
    changed[FIELD_OFFSET(16)] &= (uint8_t)~0x02u; /* explored loses floor 1 */
    fix_checksum(changed);
    assert(tower_import(b, changed, sizeof changed) == TOWER_ERR_SAVE);

    memcpy(changed, saved, sizeof saved);
    changed[FIELD_OFFSET(15)] = 1; /* cleared without goal or last-floor demon */
    fix_checksum(changed);
    assert(tower_import(b, changed, sizeof changed) == TOWER_ERR_SAVE);

    memcpy(changed, saved, sizeof saved);
    changed[FIELD_OFFSET(28)] = 0x10u; /* chapter 5 without clearing the tower */
    fix_checksum(changed);
    assert(tower_import(b, changed, sizeof changed) == TOWER_ERR_SAVE);

    memcpy(changed, saved, sizeof saved);
    changed[FIELD_OFFSET(28)] = 0x21u; /* chapter bits beyond chapter five */
    fix_checksum(changed);
    assert(tower_import(b, changed, sizeof changed) == TOWER_ERR_SAVE);

    memcpy(changed, saved, sizeof saved);
    changed[FIELD_OFFSET(1)] = 0xffu; /* status outside the enum */
    fix_checksum(changed);
    assert(tower_import(b, changed, sizeof changed) == TOWER_ERR_SAVE);

    memcpy(changed, saved, sizeof saved);
    changed[FIELD_OFFSET(5)] = 0xffu; /* hp far above the obtainable maximum */
    changed[FIELD_OFFSET(5) + 1u] = 0xffu;
    fix_checksum(changed);
    assert(tower_import(b, changed, sizeof changed) == TOWER_ERR_SAVE);

    memcpy(changed, saved, sizeof saved);
    changed[FIELD_OFFSET(8)] = 1; /* key count not backed by a consumed key */
    fix_checksum(changed);
    assert(tower_import(b, changed, sizeof changed) == TOWER_ERR_SAVE);

    memcpy(changed, saved, sizeof saved);
    changed[FIELD_OFFSET(27)] = 2; /* bool field outside 0/1 */
    fix_checksum(changed);
    assert(tower_import(b, changed, sizeof changed) == TOWER_ERR_SAVE);

    assert(tower_import(b, saved, sizeof saved - 1u) == TOWER_ERR_SAVE);
    assert(tower_hash(b) == hash);

    /* The untouched record still imports and matches. */
    import_into(b, saved);
    assert(tower_hash(b) == hash);

    tower_delete(a);
    tower_delete(b);
    printf("ok: all %u single-byte corruptions and 12 semantic forgeries rejected\n",
           (unsigned)TOWER_SAVE_BYTES);
}

int main(void)
{
    test_header_shape();
    test_wire_layout();
    test_new_game_round_trip();
    test_kill_enemy_marks_one_bit();
    test_losing_fight_is_lethal_but_keeps_enemy();
    test_secret_wall_is_permanent();
    test_event_tile();
    test_teleport_anchors();
    test_floor_shapes();
    test_chapter_gate();
    test_chapter_exit_stair();
    test_final_goal();
    test_enemy_scaling();
    test_combat_save_round_trip();
    test_corrupt_imports();
    puts("PASS: 50-floor tower model (bitmap saves, scaling, secret/event/death)");
    return 0;
}
